-- Security helpers and baseline RLS. Privileged roles are granted manually by the database owner.
create or replace function public.has_staff_role(allowed public.app_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role=any(allowed)); $$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select public.has_staff_role(array['owner','admin','finance','operations','content_manager']::public.app_role[]); $$;
alter table public.profiles enable row level security; alter table public.addresses enable row level security; alter table public.product_categories enable row level security; alter table public.products enable row level security; alter table public.product_media enable row level security; alter table public.site_sections enable row level security; alter table public.certificates enable row level security; alter table public.testimonials enable row level security; alter table public.enquiries enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.inventory_locations enable row level security; alter table public.inventory_batches enable row level security; alter table public.stock_movements enable row level security; alter table public.promotions enable row level security; alter table public.referrals enable row level security; alter table public.promotion_redemptions enable row level security; alter table public.chart_of_accounts enable row level security; alter table public.journal_entries enable row level security; alter table public.journal_lines enable row level security; alter table public.payments enable row level security; alter table public.audit_logs enable row level security;
create policy "profiles read own or staff" on public.profiles for select using(id=auth.uid() or public.is_staff());
create policy "profiles update own or staff" on public.profiles for update using(id=auth.uid() or public.is_staff()) with check((id=auth.uid() and role in ('customer','business')) or public.is_staff());
create policy "addresses own or staff" on public.addresses for all using(user_id=auth.uid() or public.is_staff()) with check(user_id=auth.uid() or public.is_staff());
create policy "public visible categories" on public.product_categories for select using(is_visible or public.is_staff()); create policy "staff manage categories" on public.product_categories for all using(public.is_staff()) with check(public.is_staff());
create policy "public active products" on public.products for select using(is_active or public.is_staff()); create policy "staff manage products" on public.products for all using(public.is_staff()) with check(public.is_staff());
create policy "media for active products" on public.product_media for select using(public.is_staff() or exists(select 1 from public.products p where p.id=product_id and p.is_active)); create policy "staff manage media" on public.product_media for all using(public.is_staff()) with check(public.is_staff());
create policy "visible site sections" on public.site_sections for select using(is_visible or public.is_staff()); create policy "staff manage site sections" on public.site_sections for all using(public.is_staff()) with check(public.is_staff());
create policy "public certificates" on public.certificates for select using(is_public or public.is_staff()); create policy "staff manage certificates" on public.certificates for all using(public.is_staff()) with check(public.is_staff());
create policy "visible approved testimonials" on public.testimonials for select using((approved and is_visible) or public.is_staff()); create policy "staff manage testimonials" on public.testimonials for all using(public.is_staff()) with check(public.is_staff());
create policy "create enquiries" on public.enquiries for insert with check(user_id is null or user_id=auth.uid()); create policy "read own enquiries or staff" on public.enquiries for select using(user_id=auth.uid() or public.is_staff()); create policy "staff manage enquiries" on public.enquiries for update using(public.is_staff()) with check(public.is_staff());
create policy "orders own or staff" on public.orders for select using(user_id=auth.uid() or public.is_staff()); create policy "staff manage orders" on public.orders for all using(public.is_staff()) with check(public.is_staff());
create policy "order items through own order" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_staff()))); create policy "staff manage order items" on public.order_items for all using(public.is_staff()) with check(public.is_staff());
create policy "inventory staff only" on public.inventory_locations for all using(public.is_staff()) with check(public.is_staff()); create policy "batches staff only" on public.inventory_batches for all using(public.is_staff()) with check(public.is_staff()); create policy "movements staff only" on public.stock_movements for all using(public.is_staff()) with check(public.is_staff());
create policy "active promotions read" on public.promotions for select using(is_active or public.is_staff()); create policy "staff manage promotions" on public.promotions for all using(public.is_staff()) with check(public.is_staff());
create policy "own referrals or staff" on public.referrals for select using(referrer_user_id=auth.uid() or referred_user_id=auth.uid() or public.is_staff()); create policy "staff manage referrals" on public.referrals for all using(public.is_staff()) with check(public.is_staff());
create policy "own redemptions or staff" on public.promotion_redemptions for select using(user_id=auth.uid() or public.is_staff()); create policy "staff manage redemptions" on public.promotion_redemptions for all using(public.is_staff()) with check(public.is_staff());
create policy "staff chart of accounts" on public.chart_of_accounts for all using(public.has_staff_role(array['owner','admin','finance']::public.app_role[])) with check(public.has_staff_role(array['owner','admin','finance']::public.app_role[]));
create policy "staff journal entries" on public.journal_entries for all using(public.has_staff_role(array['owner','admin','finance']::public.app_role[])) with check(public.has_staff_role(array['owner','admin','finance']::public.app_role[]));
create policy "staff journal lines" on public.journal_lines for all using(public.has_staff_role(array['owner','admin','finance']::public.app_role[])) with check(public.has_staff_role(array['owner','admin','finance']::public.app_role[]));
create policy "own payments or staff" on public.payments for select using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_staff()))); create policy "staff manage payments" on public.payments for all using(public.is_staff()) with check(public.is_staff());
create policy "audit visible to owner admin finance" on public.audit_logs for select using(public.has_staff_role(array['owner','admin','finance']::public.app_role[]));
-- Accounting post operation: balanced lines required; posted journals are immutable. Use a privileged server-side function for posting.
create or replace function public.guard_posted_journal() returns trigger language plpgsql as $$ begin if old.status in ('posted','reversed') then raise exception 'Posted or reversed journal entries are immutable; create a reversal instead.'; end if; return new; end; $$;
create trigger immutable_posted_journal before update or delete on public.journal_entries for each row when (old.status in ('posted','reversed')) execute function public.guard_posted_journal();
create or replace function public.guard_posted_journal_lines() returns trigger language plpgsql as $$ declare entry_status public.journal_status; target_id uuid; begin target_id:=coalesce(new.journal_entry_id,old.journal_entry_id); select status into entry_status from public.journal_entries where id=target_id; if entry_status in ('posted','reversed') then raise exception 'Lines of posted or reversed journals are immutable.'; end if; return coalesce(new,old); end; $$;
create trigger immutable_posted_journal_lines before insert or update or delete on public.journal_lines for each row execute function public.guard_posted_journal_lines();
-- Seed chart of accounts. Amounts in application are integer minor units (paise for INR).
insert into public.chart_of_accounts(code,name,account_type,is_control_account) values
('1000','Cash and Bank','asset',true),('1100','Accounts Receivable','asset',true),('1200','Inventory','asset',true),('1300','Input GST Receivable','asset',true),('2000','Accounts Payable','liability',true),('2100','Output GST Payable','liability',true),('2200','Customer Advances','liability',true),('3000','Owner Capital','equity',false),('3100','Retained Earnings','equity',false),('4000','Product Sales','revenue',false),('4100','Sales Returns and Discounts','revenue',false),('5000','Cost of Goods Sold','expense',false),('6000','Freight and Delivery Expense','expense',false),('6100','Marketing and Referral Expense','expense',false),('6200','General Operating Expenses','expense',false)
on conflict(code) do nothing;
